<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref} from 'vue'
import {Refresh} from '@element-plus/icons-vue'
import {oaApi} from '@/api/oa'
import {canOA,messageOf,useOACommands,oaLabel} from '@/utils/oa'
import type {Instance,Named,Reconciliation,Seat} from '@/types/oa'
const {busy,error,run}=useOACommands(),rows=ref<Instance[]>([]),selected=ref<Instance|null>(null),candidates=ref<Record<string,Named[]>>({}),reconciliation=ref<Reconciliation|null>(null),reason=ref(''),target=ref<Record<string,string>>({})
const canRead=computed(()=>canOA('workflow_admin')),canWrite=computed(()=>canOA('workflow_admin','write'))
const active=computed(()=>!!selected.value&&['IN_REVIEW','PAUSED'].includes(selected.value.state))
let request=0
const actionable=(node:Instance['nodes'][number],seat:Seat)=>active.value&&['ACTIVE','WAITING'].includes(node.state)&&seat.state==='PENDING'
const transferable=(node:Instance['nodes'][number],seat:Seat)=>actionable(node,seat)&&!seat.substituted
function clear(){selected.value=null;candidates.value={};target.value={};reason.value='';request++}
async function load(){if(!canRead.value){error.value='当前账号没有流程管理读取权限';return}const id=selected.value?.instance_id;clear();try{rows.value=await oaApi.instances();reconciliation.value=null;const row=rows.value.find(r=>r.instance_id===id);if(row)await open(row)}catch(e){error.value=messageOf(e)}}
async function open(row:Instance){if(busy.value)return;clear();selected.value=row;const ticket=++request;for(const node of row.nodes)for(const seat of node.seats){if(!actionable(node,seat))continue;try{const values=await oaApi.candidates(seat.id);if(ticket!==request)return;candidates.value[seat.id]=values}catch(e){if(ticket===request)error.value=messageOf(e)}}}
async function transfer(seatId:string){const value=selected.value;if(!canWrite.value||!value||!target.value[seatId]||!reason.value.trim())return;const node=value.nodes.find(item=>item.seats.some(seat=>seat.id===seatId));const seat=node?.seats.find(s=>s.id===seatId);if(!node||!seat||!transferable(node,seat))return;const result=await run(`transfer:${seatId}`,{expected_revision:node.revision,target_user_id:target.value[seatId],reason:reason.value},p=>oaApi.transfer(seatId,p));if(result)await load()}
async function resume(){const value=selected.value;if(!canWrite.value||value?.state!=='PAUSED'||!reason.value.trim())return;const allowed=new Set(value.nodes.flatMap(n=>n.seats.filter(s=>actionable(n,s)).map(s=>s.id)));const replacements=Object.entries(target.value).filter(([id,user])=>user&&allowed.has(id)).map(([seat_id,target_user_id])=>({seat_id,target_user_id}));const result=await run(`resume:${value.instance_id}`,{expected_revision:value.revision,replacements,reason:reason.value},p=>oaApi.resume(value.instance_id,p));if(result)await load()}
async function reconcile(){if(!canRead.value)return;try{reconciliation.value=await oaApi.reconcile()}catch(e){error.value=messageOf(e)}}
onMounted(load);onBeforeUnmount(()=>request++)
</script>
<template><main class="workbench manual-oa" v-loading="busy"><header class="page-heading"><h1>异常与流程管理</h1><div class="actions"><el-button :icon="Refresh" :disabled="busy" @click="load">刷新</el-button><el-button :disabled="busy||!canRead" @click="reconcile">运行只读对账</el-button></div></header><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-empty v-if="!canRead" description="没有流程管理读取权限"/><div v-else class="oa-two-pane"><section class="oa-section"><h2>流程记录</h2><el-table :data="rows" empty-text="暂无实例" @row-click="open"><el-table-column prop="business_no" label="申请编号" min-width="190"/><el-table-column label="状态"><template #default="{row}">{{oaLabel(row.state)}}</template></el-table-column><el-table-column prop="pause_reason" label="暂停原因"/></el-table></section><section class="oa-section" v-if="selected"><h2>{{selected.business_no}}</h2><p class="muted">实例版本 {{selected.revision}}，路线版本 {{selected.route_revision}}</p><div v-for="node in selected.nodes" :key="node.id" class="node-row"><strong>{{node.ordinal+1}}. {{node.kind==='approval'?'审批节点':node.kind==='cc'?'抄送节点':'结束节点'}}</strong><span>{{oaLabel(node.state)}}</span><div v-for="(seat,index) in node.seats" :key="seat.id" class="seat-row"><span>{{seat.effective_user_name||('办理人 '+(index+1))}} · {{oaLabel(seat.state)}}</span><el-select v-if="canWrite&&actionable(node,seat)&&candidates[seat.id]?.length" v-model="target[seat.id]" :aria-label="'替代人员 '+(index+1)" :disabled="busy" placeholder="选择替代人员"><el-option v-for="candidate in candidates[seat.id]" :key="candidate.id" :label="candidate.name" :value="candidate.id"/></el-select><el-button v-if="canWrite&&transferable(node,seat)" link type="primary" :disabled="busy||!target[seat.id]||!reason.trim()" @click="transfer(seat.id)">转交</el-button></div></div><el-form v-if="canWrite&&active" label-position="top"><el-form-item label="操作理由"><el-input v-model="reason" aria-label="操作理由" :disabled="busy"/></el-form-item><el-button v-if="selected.state==='PAUSED'" type="primary" :disabled="busy||!reason.trim()" @click="resume">恢复暂停流程</el-button></el-form></section></div><section v-if="reconciliation" class="oa-section"><h2>只读对账结果</h2><el-alert :title="reconciliation.ok?'对账通过':'发现需要人工处理的问题'" :type="reconciliation.ok?'success':'warning'" :closable="false"/><p>检查 {{reconciliation.checked}} 项，{{reconciliation.issues.length}} 个问题。</p><el-table :data="reconciliation.issues" empty-text="没有问题"><el-table-column prop="leave_id" label="申请编号"/><el-table-column label="问题"><template #default="{row}">{{oaLabel(row.code)}}</template></el-table-column></el-table></section></main></template>
